def model(p, kind):
    p1,p2,al,q=p
    A=P**p1
    if kind==0: B=np.exp(-al*t); C=P**p2*t**q
    if kind==1: B=np.exp(-al*t); C=P**p2*np.exp(q*t)
    if kind==2: B=t**q; C=P**p2*np.exp(-al*t)
    if kind==3: B=np.log(t)*0+t**q; C=P**p2*np.log(t)
    if kind==4: B=np.exp(-al*t); C=P**p2*np.log(1+q*t)
    return np.c_[A,B,C]
